// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a simple ERC20-like token that reverts on transferFrom
        TokenRevert token = new TokenRevert();
        address from = address(0xbeef);
        address[] memory tos = new address[](1);
        tos[0] = address(0xdead);
        // The reference will require the external call to succeed; it reverts.
        // The buggy version does not make the call, so it returns true.
        bool ok;
        try c.transfer(from, address(token), tos, 100) {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference reverts (ok false), buggy returns true (ok true)
        assertTrue(ok);
    }
}

contract TokenRevert {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        revert("fail");
    }
}
